\documentclass[border=10pt]{standalone}
\usepackage{pgfplots}
\usepgfplotslibrary{colormaps}
\pgfplotsset{compat=1.18}

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    width=12cm,
    height=8cm,
    xlabel=$x$,
    ylabel=$y$,
    title={Trace in $xy$-plane ($z=0$): $x^2 + \frac{y^2}{36} = 1$},
    axis lines=middle,
    xmin=-1.5, xmax=1.5,
    ymin=-7, ymax=7,
    axis equal image,
    grid=major,
    legend pos=south east,
    samples=100,
    domain=0:360,
]
\addplot+[mark=none, thick, blue] ({cos(x)}, {6*sin(x)});
\addlegendentry{Ellipse}
\end{axis}
\end{tikzpicture}
\end{document}

